  /** Country code (default: 'BE') */
  country: string
  // Index signature required by DataTable<T extends Record<string, unknown>>
  [key: string]: unknown
}

/** Display name computed from customer type and fields. */
export function getDisplayName(customer: CustomerDetail): string {
  return customer.type === 'private'
    ? [customer.firstName, customer.lastName].filter(Boolean).join(' ').trim() || ''
    : (customer.companyName ?? '')
}

// ---------------------------------------------------------------------------
// Pagination shapes
// ---------------------------------------------------------------------------

/** Paginated response from the management list endpoint. */
export interface CustomerPaginatedResponse {
  customers: CustomerDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

/**
 * useCustomers — Data fetching hook for the customer management list.
 *
 * Handles:
 * - Initial data load via GET /api/customers (paginated)
 * - Debounced search filtering across name, email, phone fields
 * - Pagination state management (25 per page by default)
 * - Loading and error states
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { fetchCustomers } from '../api.js'
import type { CustomerDetail, CustomerPaginatedResponse } from '../types.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_PAGE_SIZE = 25
const SEARCH_DEBOUNCE_MS = 300

// ---------------------------------------------------------------------------
// Hook State & Actions Interfaces
// ---------------------------------------------------------------------------

interface UseCustomersState {
  /** Paginated customer data */
  customers: CustomerDetail[]
  /** Total number of matching customers (for pagination) */
  totalItems: number
  /** Current page number (1-indexed) */
  currentPage: number
  /** Items per page */
  pageSize: number
  /** Total pages based on current search results */
  totalPages: number
  /** Current search term */
  searchTerm: string
  /** Whether data is currently being fetched */
  isLoading: boolean
  /** Error message from failed API calls, or null */
  error: string | null
}

interface UseCustomersActions {
  /** Set the search term (triggers debounced fetch) */
  setSearchTerm: (term: string) => void
  /** Navigate to a specific page */
  goToPage: (page: number) => void
  /** Reset pagination to page 1 and refetch */
  refresh: () => void
}

export type UseCustomersResult = UseCustomersState & UseCustomersActions

// ---------------------------------------------------------------------------
// Hook Implementation
// ---------------------------------------------------------------------------

/**
 * Custom hook for fetching and managing the customer list.
 *
 * Provides paginated results with debounced search filtering.
 */
export function useCustomers(): UseCustomersResult {
  const [customers, setCustomers] = useState<CustomerDetail[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize] = useState(DEFAULT_PAGE_SIZE)
  const [searchTerm, setSearchTermState] = useState('')
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Ref for debounce timer
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // Debounced search term — actual value used in API calls
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('')

  // -----------------------------------------------------------------------
  // Data fetching
  // -----------------------------------------------------------------------

  const fetchCustomerData = useCallback(async () => {
    setIsLoading(true)
    setError(null)

    try {
      const response: CustomerPaginatedResponse = await fetchCustomers({
        search: debouncedSearchTerm || undefined,
        page: currentPage,
        pageSize,
      })

      setCustomers(response.customers)
      setTotalItems(response.totalItems)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load customers'
      setError(message)
      setCustomers([])
      setTotalItems(0)
    } finally {
      setIsLoading(false)
    }
  }, [debouncedSearchTerm, currentPage, pageSize])

  // -----------------------------------------------------------------------
  // Search debouncing
  // -----------------------------------------------------------------------

  const setSearchTerm = useCallback((term: string) => {
    setSearchTermState(term)

    // Clear existing timer
    if (searchTimerRef.current) {
      clearTimeout(searchTimerRef.current)
    }

    // Set new debounce timer
    searchTimerRef.current = setTimeout(() => {
      setDebouncedSearchTerm(term)
      // Reset to page 1 when search changes
      setCurrentPage(1)
    }, SEARCH_DEBOUNCE_MS)
  }, [])

  // -----------------------------------------------------------------------
  // Pagination
  // -----------------------------------------------------------------------

  const goToPage = useCallback((page: number) => {
    setCurrentPage(page)
  }, [])

  const refresh = useCallback(() => {
    fetchCustomerData()
  }, [fetchCustomerData])

  // -----------------------------------------------------------------------
  // Derived state
  // -----------------------------------------------------------------------

  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize))

  // -----------------------------------------------------------------------
  // Effects
  // -----------------------------------------------------------------------

  // Fetch data when search term or page changes
  useEffect(() => {
    fetchCustomerData()
  }, [fetchCustomerData])

  // Cleanup debounce timer on unmount
  useEffect(() => {
    return () => {
      if (searchTimerRef.current) {
        clearTimeout(searchTimerRef.current)
      }
    }
  }, [])

  // -----------------------------------------------------------------------
  // Return
  // -----------------------------------------------------------------------

  return {
    customers,
    totalItems,
    currentPage,
    pageSize,
    totalPages,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  }
}

/**
 * CustomersPage — Management list page for customers.
 *
 * Displays a searchable, paginated DataTable with columns for:
 * - Name (computed from type)
 * - Type badge (Private/Company)
 * - Contact info (email/phone)
 * - Actions (Edit/Delete buttons)
 */

import { useCallback, useState } from 'react'
import toast from 'react-hot-toast'
import { useCustomers } from '../hooks/useCustomers.js'
import {
  DataTable,
  type DataTableColumn,
} from '@/components/ui/DataTable.js'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog.js'
import { Button } from '@/components/ui/button.js'
import type { CustomerDetail } from '../types.js'
import { getDisplayName } from '../types.js'
import { CustomerFormDialog } from './CustomerFormDialog.js'

// ---------------------------------------------------------------------------
// Column Definitions
// ---------------------------------------------------------------------------

function TypeBadge({ type }: { type: 'private' | 'company' }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        type === 'private'
          ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'
          : 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300'
      }`}
    >
      {type === 'private' ? 'Private' : 'Company'}
    </span>
  )
}

function ContactInfo({ customer }: { customer: CustomerDetail }) {
  const contacts = [customer.email, customer.phone].filter(Boolean)

  if (contacts.length === 0) {
    return <span className="text-muted-foreground">—</span>
  }

  return (
    <div className="flex flex-col gap-0.5 text-sm">
      {customer.email && (
        <a href={`mailto:${customer.email}`} className="text-blue-600 hover:underline">
          {customer.email}
        </a>
      )}
      {customer.phone && (
        <span>{customer.phone}</span>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Page Component
// ---------------------------------------------------------------------------

export function CustomersPage() {
  const {
    customers,
    totalItems,
    currentPage,
    pageSize,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  } = useCustomers()

  // -----------------------------------------------------------------------
  // Form dialog state (create + edit via single component)
  // -----------------------------------------------------------------------

  const [formDialogOpen, setFormDialogOpen] = useState(false)
  const [editingCustomer, setEditingCustomer] = useState<CustomerDetail | null>(null)

  // -----------------------------------------------------------------------
  // Delete confirmation dialog state
  // -----------------------------------------------------------------------

  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)
  const [deletingCustomer, setDeletingCustomer] = useState<CustomerDetail | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  // -----------------------------------------------------------------------
  // Action handlers — Edit, Delete, Create
  // -----------------------------------------------------------------------

  const openCreateDialog = useCallback(() => {
    setEditingCustomer(null)
    setFormDialogOpen(true)
  }, [])

  const handleEdit = useCallback((customer: CustomerDetail) => {
    setEditingCustomer(customer)
    setFormDialogOpen(true)
  }, [])

  const openDeleteDialog = useCallback((customer: CustomerDetail) => {
    setDeletingCustomer(customer)
    setDeleteDialogOpen(true)
  }, [])

  const handleConfirmDelete = useCallback(async () => {
    if (!deletingCustomer) return

    setIsDeleting(true)

    try {
      const response = await fetch(`/api/customers/${deletingCustomer.id}`, { method: 'DELETE' })

      if (!response.ok) {
        const body = await response.json().catch(() => ({}))
        const message = (body as { error?: string }).error ?? `Delete failed: ${response.status}`
        // Show toast for blocked deletes and other errors
        toast.error(message)
        return
      }

      setDeleteDialogOpen(false)
      toast.success('Customer deleted successfully')
      refresh()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to delete customer'
      toast.error(message)
    } finally {
      setIsDeleting(false)
    }
  }, [deletingCustomer, refresh])

  const closeDeleteDialog = useCallback(() => {
    setDeleteDialogOpen(false)
    setDeletingCustomer(null)
    setIsDeleting(false)
  }, [])

  // -----------------------------------------------------------------------
  // Form dialog callbacks
  // -----------------------------------------------------------------------

  const handleFormSaveSuccess = useCallback(() => {
    toast.success(editingCustomer ? 'Customer updated successfully' : 'Customer created successfully')
    refresh()
  }, [editingCustomer, refresh])

  // -----------------------------------------------------------------------
  // Column definitions for DataTable
  // ---------------------------------------------------------------------------

  const columns: DataTableColumn<CustomerDetail>[] = [
    {
      key: 'name',
      header: 'Name',
      render: (customer: CustomerDetail) => (
        <span className="font-medium">{getDisplayName(customer)}</span>
      ),
    },
    {
      key: 'type',
      header: 'Type',
      render: (customer: CustomerDetail) => (
        <TypeBadge type={customer.type} />
      ),
    },
    {
      key: 'contact',
      header: 'Contact',
      render: (customer: CustomerDetail) => (
        <ContactInfo customer={customer} />
      ),
    },
    {
      key: 'actions',
      header: 'Actions',
      render: (customer: CustomerDetail) => (
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => handleEdit(customer)}
          >
            Edit
          </Button>
          <Button
            variant="destructive"
            size="sm"
            onClick={() => openDeleteDialog(customer)}
          >
            Delete
          </Button>
        </div>
      ),
    },
  ]

  // -----------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <div className="space-y-6">
      {/* Page header */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Customers</h1>
        <p className="text-muted-foreground mt-1">
          Manage your customer records. Search, filter, and paginate through the list.
        </p>
      </div>

      {/* Error banner */}
      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
          <p className="font-medium">Error loading customers</p>
          <p>{error}</p>
          <Button variant="outline" size="sm" onClick={refresh} className="mt-2">
            Retry
          </Button>
        </div>
      )}

      {/* Toolbar — New Customer button */}
      <div className="flex justify-end">
        <Button onClick={openCreateDialog}>New Customer</Button>
      </div>

      {/* DataTable */}
      <DataTable<CustomerDetail>
        data={customers}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={goToPage}
        isLoading={isLoading}
        emptyMessage="No customers found"
      />

      {/* Form dialog (create + edit) */}
      <CustomerFormDialog
        open={formDialogOpen}
        onOpenChange={(open) => {
          setFormDialogOpen(open)
          if (!open) {
            setEditingCustomer(null)
          }
        }}
        editingCustomer={editingCustomer}
        onSaveSuccess={handleFormSaveSuccess}
      />

      {/* Delete confirmation dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={closeDeleteDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Delete customer</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete{' '}
              <strong>{deletingCustomer ? getDisplayName(deletingCustomer) : ''}</strong>?
              This action cannot be undone. If the customer has related records
              (sales, invoices, quotes, repairs), deletion will be blocked.
            </DialogDescription>
          </DialogHeader>



          <DialogFooter>
            <Button variant="outline" onClick={closeDeleteDialog} disabled={isDeleting}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleConfirmDelete}
              disabled={isDeleting || !deletingCustomer}
            >
              {isDeleting ? 'Deleting...' : 'Delete'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

