import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { users } from '@/db/schema.js'

describe('Users Routes — Paginated Staff List', () => {
  async function resetUsers() {
    await db.delete(users)
  }

  beforeEach(async () => {
    await resetUsers()
  })

  describe('GET /api/users (compact dropdown mode)', () => {
    it('should return 200 with empty array when no users exist', async () => {
      const res = await app.request('/api/users')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(Array.isArray(body)).toBe(true)
      expect(body).toEqual([])
    })

    it('should return only active workers in compact shape', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Jan Kowalski', role: 'mechanic', hourlyRate: 4500, isActive: true },
        { id: 'u2', name: 'Anna Nowak', role: 'manager', hourlyRate: 6000, isActive: false },
      ])

      const res = await app.request('/api/users')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Array<Record<string, unknown>>
      expect(body).toHaveLength(1)
      expect(body[0].name).toBe('Jan Kowalski')

      // Compact shape: id, name, role only
      const keys = Object.keys(body[0]).sort()
      expect(keys).toEqual(['id', 'name', 'role'])
    })

    it('should return workers sorted by name', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Zbigniew Zalewski', role: 'mechanic', hourlyRate: 4500, isActive: true },
        { id: 'u2', name: 'Adam Adamski', role: 'mechanic', hourlyRate: 4000, isActive: true },
      ])

      const res = await app.request('/api/users')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Array<Record<string, unknown>>
      expect(body.map((u) => u.name)).toEqual(['Adam Adamski', 'Zbigniew Zalewski'])
    })
  })

  describe('GET /api/users?search= (paginated mode)', () => {
    it('should return paginated response with full details when query params present', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Jan Kowalski', role: 'mechanic', hourlyRate: 4500, isActive: true },
        { id: 'u2', name: 'Anna Nowak', role: 'manager', hourlyRate: 6000, isActive: false },
      ])

      const res = await app.request('/api/users?page=1&pageSize=25')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      expect(body.users).toBeDefined()
      expect(body.totalItems).toBe(2)
      expect(body.currentPage).toBe(1)
      expect(body.pageSize).toBe(25)
      expect(body.totalPages).toBe(1)

      // Full detail shape includes all fields
      const user = (body.users as Array<Record<string, unknown>>)[0]
      expect(user).toHaveProperty('id')
      expect(user).toHaveProperty('name')
      expect(user).toHaveProperty('role')
      expect(user).toHaveProperty('hourlyRate')
      expect(user).toHaveProperty('isActive')
      expect(user).toHaveProperty('createdAt')
    })

    it('should include both active and inactive users in paginated mode', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Active User', role: 'mechanic', hourlyRate: 4500, isActive: true },
        { id: 'u2', name: 'Inactive User', role: 'manager', hourlyRate: 6000, isActive: false },
      ])

      const res = await app.request('/api/users?page=1&pageSize=25')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      expect((body.users as Array<Record<string, unknown>>).length).toBe(2)
    })

    it('should filter by name using search param', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Jan Kowalski', role: 'mechanic', hourlyRate: 4500, isActive: true },
        { id: 'u2', name: 'Anna Nowak', role: 'manager', hourlyRate: 6000, isActive: true },
        { id: 'u3', name: 'Janusz Janowski', role: 'mechanic', hourlyRate: 5000, isActive: true },
      ])

      const res = await app.request('/api/users?search=jan&page=1&pageSize=25')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      expect((body.users as Array<Record<string, unknown>>).length).toBe(2)
      expect(body.totalItems).toBe(2)

      // Verify both matching names are returned
      const names = (body.users as Array<Record<string, unknown>>).map((u) => u.name as string)
      expect(names).toContain('Jan Kowalski')
      expect(names).toContain('Janusz Janowski')
    })

    it('should be case-insensitive for search', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Jan Kowalski', role: 'mechanic', hourlyRate: 4500, isActive: true },
      ])

      const res = await app.request('/api/users?search=JAN&page=1&pageSize=25')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      expect((body.users as Array<Record<string, unknown>>).length).toBe(1)
    })

    it('should return empty paginated response when search has no matches', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Jan Kowalski', role: 'mechanic', hourlyRate: 4500, isActive: true },
      ])

      const res = await app.request('/api/users?search=nonexistent&page=1&pageSize=25')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      expect((body.users as Array<Record<string, unknown>>).length).toBe(0)
      expect(body.totalItems).toBe(0)
    })

    it('should respect pageSize limit', async () => {
      // Insert 30 users
      const seedUsers = Array.from({ length: 30 }, (_, i) => ({
        id: `u${i}`,
        name: `User ${String(i).padStart(2, '0')}`,
        role: (i % 2 === 0 ? 'mechanic' : 'manager') as 'mechanic' | 'manager',
        hourlyRate: 4500 + i * 100,
        isActive: true,
      }))
      await db.insert(users).values(seedUsers)

      const res = await app.request('/api/users?page=1&pageSize=10')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      expect((body.users as Array<Record<string, unknown>>).length).toBe(10)
      expect(body.totalItems).toBe(30)
      expect(body.currentPage).toBe(1)
      expect(body.pageSize).toBe(10)
      expect(body.totalPages).toBe(3)
    })

    it('should return second page of results', async () => {
      const seedUsers = Array.from({ length: 30 }, (_, i) => ({
        id: `u${i}`,
        name: `User ${String(i).padStart(2, '0')}`,
        role: (i % 2 === 0 ? 'mechanic' : 'manager') as 'mechanic' | 'manager',
        hourlyRate: 4500 + i * 100,
        isActive: true,
      }))
      await db.insert(users).values(seedUsers)

      const res = await app.request('/api/users?page=2&pageSize=10')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      expect((body.users as Array<Record<string, unknown>>).length).toBe(10)
      expect(body.currentPage).toBe(2)
    })

    it('should return users sorted by name in paginated mode', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Zbigniew Zalewski', role: 'mechanic', hourlyRate: 4500, isActive: true },
        { id: 'u2', name: 'Adam Adamski', role: 'mechanic', hourlyRate: 4000, isActive: true },
      ])

      const res = await app.request('/api/users?page=1&pageSize=25')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      const names = (body.users as Array<Record<string, unknown>>).map((u) => u.name as string)
      expect(names).toEqual(['Adam Adamski', 'Zbigniew Zalewski'])
    })

    it('should return hourlyRate in cents', async () => {
      await db.insert(users).values([
        { id: 'u1', name: 'Jan Kowalski', role: 'mechanic', hourlyRate: 4500, isActive: true },
      ])

      const res = await app.request('/api/users?page=1&pageSize=25')
      expect(res.status).toBe(200)

      const body = (await res.json()) as Record<string, unknown>
      const user = (body.users as Array<Record<string, unknown>>)[0]
      expect(user.hourlyRate).toBe(4500) // 4500 cents = €45.00/h
    })
  })
})

/**
 * Staff — Frontend types.
 */

// ---------------------------------------------------------------------------
// Re-export shared domain types
// ---------------------------------------------------------------------------

export type { StaffMember, NewStaffMember, UpdateStaffMember } from '@shared/types/staff.js'

// ---------------------------------------------------------------------------
// Frontend DTOs (mirroring backend response shapes)
// ---------------------------------------------------------------------------

/** Full staff member detail returned by the paginated list endpoint. */
export interface StaffMemberDetail {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date | string
  // Index signature required by DataTable<T extends Record<string, unknown>>
  [key: string]: unknown
}

/** Paginated response from the staff management list endpoint. */
export interface StaffPaginatedResponse {
  users: StaffMemberDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Display helpers
// ---------------------------------------------------------------------------

/** Format hourly rate (cents) as currency string with /h suffix. */
export function formatHourlyRate(cents: number): string {
  const euros = cents / 100
  return `€${euros.toFixed(2)}/h`
}

/**
 * Staff — API client functions.
 */

import type { StaffPaginatedResponse } from './types.js'

const BASE_URL = '' // relative to current origin

// ---------------------------------------------------------------------------
// Management List (paginated + searchable)
// ---------------------------------------------------------------------------

export async function fetchStaffMembers({
  search,
  page = 1,
  pageSize = 25,
}: {
  search?: string
  page?: number
  pageSize?: number
}): Promise<StaffPaginatedResponse> {
  const params = new URLSearchParams()

  if (search !== undefined && search !== '') {
    params.set('search', search)
  }
  params.set('page', String(page))
  params.set('pageSize', String(pageSize))

  const response = await fetch(`${BASE_URL}/api/users?${params}`)

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to load staff members: ${response.status}`)
  }

  return response.json() as Promise<StaffPaginatedResponse>
}

/**
 * useStaffMembers — Data fetching hook for the staff management list.
 *
 * Handles:
 * - Initial data load via GET /api/users (paginated)
 * - Debounced search filtering by name
 * - Pagination state management (25 per page by default)
 * - Loading and error states
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { fetchStaffMembers } from '../api.js'
import type { StaffMemberDetail, StaffPaginatedResponse } from '../types.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_PAGE_SIZE = 25
const SEARCH_DEBOUNCE_MS = 300

// ---------------------------------------------------------------------------
// Hook State & Actions Interfaces
// ---------------------------------------------------------------------------

interface UseStaffMembersState {
  /** Paginated staff member data */
  staffMembers: StaffMemberDetail[]
  /** Total number of matching staff members (for pagination) */
  totalItems: number
  /** Current page number (1-indexed) */
  currentPage: number
  /** Items per page */
  pageSize: number
  /** Total pages based on current search results */
  totalPages: number
  /** Current search term */
  searchTerm: string
  /** Whether data is currently being fetched */
  isLoading: boolean
  /** Error message from failed API calls, or null */
  error: string | null
}

interface UseStaffMembersActions {
  /** Set the search term (triggers debounced fetch) */
  setSearchTerm: (term: string) => void
  /** Navigate to a specific page */
  goToPage: (page: number) => void
  /** Reset pagination to page 1 and refetch */
  refresh: () => void
}

export type UseStaffMembersResult = UseStaffMembersState & UseStaffMembersActions

// ---------------------------------------------------------------------------
// Hook Implementation
// ---------------------------------------------------------------------------

/**
 * Custom hook for fetching and managing the staff member list.
 *
 * Provides paginated results with debounced search filtering by name.
 */
export function useStaffMembers(): UseStaffMembersResult {
  const [staffMembers, setStaffMembers] = useState<StaffMemberDetail[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize] = useState(DEFAULT_PAGE_SIZE)
  const [searchTerm, setSearchTermState] = useState('')
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Ref for debounce timer
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // Debounced search term — actual value used in API calls
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('')

  // -----------------------------------------------------------------------
  // Data fetching
  // -----------------------------------------------------------------------

  const fetchStaffData = useCallback(async () => {
    setIsLoading(true)
    setError(null)

    try {
      const response: StaffPaginatedResponse = await fetchStaffMembers({
        search: debouncedSearchTerm || undefined,
        page: currentPage,
        pageSize,
      })

      setStaffMembers(response.users)
      setTotalItems(response.totalItems)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load staff members'
      setError(message)
      setStaffMembers([])
      setTotalItems(0)
    } finally {
      setIsLoading(false)
    }
  }, [debouncedSearchTerm, currentPage, pageSize])

  // -----------------------------------------------------------------------
  // Search debouncing
  // -----------------------------------------------------------------------

  const setSearchTerm = useCallback((term: string) => {
    setSearchTermState(term)

    // Clear existing timer
    if (searchTimerRef.current) {
      clearTimeout(searchTimerRef.current)
    }

    // Set new debounce timer
    searchTimerRef.current = setTimeout(() => {
      setDebouncedSearchTerm(term)
      // Reset to page 1 when search changes
      setCurrentPage(1)
    }, SEARCH_DEBOUNCE_MS)
  }, [])

  // -----------------------------------------------------------------------
  // Pagination
  // -----------------------------------------------------------------------

  const goToPage = useCallback((page: number) => {
    setCurrentPage(page)
  }, [])

  const refresh = useCallback(() => {
    fetchStaffData()
  }, [fetchStaffData])

  // -----------------------------------------------------------------------
  // Derived state
  // -----------------------------------------------------------------------

  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize))

  // -----------------------------------------------------------------------
  // Effects
  // -----------------------------------------------------------------------

  // Fetch data when search term or page changes
  useEffect(() => {
    fetchStaffData()
  }, [fetchStaffData])

  // Cleanup debounce timer on unmount
  useEffect(() => {
    return () => {
      if (searchTimerRef.current) {
        clearTimeout(searchTimerRef.current)
      }
    }
  }, [])

  // -----------------------------------------------------------------------
  // Return
  // -----------------------------------------------------------------------

  return {
    staffMembers,
    totalItems,
    currentPage,
    pageSize,
    totalPages,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  }
}

/**
 * StaffListPage — Management list page for staff members.
 *
 * Displays a searchable, paginated DataTable with columns for:
 * - Name
 * - Role badge (Mechanic/Manager)
 * - Hourly rate (displayed as currency €X.XX/h)
 * - Active status badge
 */

import { useStaffMembers } from '../hooks/useStaffMembers.js'
import type { StaffMemberDetail } from '../types.js'
import { formatHourlyRate } from '../types.js'
import {
  DataTable,
  type DataTableColumn,
} from '@/components/ui/DataTable.js'
import { Button } from '@/components/ui/button.js'

// ---------------------------------------------------------------------------
// Column Cell Components
// ---------------------------------------------------------------------------

function RoleBadge({ role }: { role: 'mechanic' | 'manager' }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        role === 'mechanic'
          ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300'
          : 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'
      }`}
    >
      {role === 'mechanic' ? 'Mechanic' : 'Manager'}
    </span>
  )
}

function ActiveBadge({ isActive }: { isActive: boolean }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        isActive
          ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-300'
          : 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300'
      }`}
    >
      {isActive ? 'Active' : 'Inactive'}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Page Component
// ---------------------------------------------------------------------------

export function StaffListPage() {
  const {
    staffMembers,
    totalItems,
    currentPage,
    pageSize,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  } = useStaffMembers()

  // -----------------------------------------------------------------------
  // Column definitions for DataTable
  // ---------------------------------------------------------------------------

  const columns: DataTableColumn<StaffMemberDetail>[] = [
    {
      key: 'name',
      header: 'Name',
      render: (staff: StaffMemberDetail) => (
        <span className="font-medium">{staff.name}</span>
      ),
    },
    {
      key: 'role',
      header: 'Role',
      render: (staff: StaffMemberDetail) => (
        <RoleBadge role={staff.role} />
      ),
    },
    {
      key: 'hourlyRate',
      header: 'Hourly Rate',
      render: (staff: StaffMemberDetail) => (
        <span>{formatHourlyRate(staff.hourlyRate)}</span>
      ),
    },
    {
      key: 'isActive',
      header: 'Status',
      render: (staff: StaffMemberDetail) => (
        <ActiveBadge isActive={staff.isActive} />
      ),
    },
  ]

  // -----------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <div className="space-y-6">
      {/* Page header */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Staff Members</h1>
        <p className="text-muted-foreground mt-1">
          View and manage your team roster. Search by name to find specific staff members.
        </p>
      </div>

      {/* Error banner */}
      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
          <p className="font-medium">Error loading staff members</p>
          <p>{error}</p>
          <Button variant="outline" size="sm" onClick={refresh} className="mt-2">
            Retry
          </Button>
        </div>
      )}

      {/* DataTable */}
      <DataTable<StaffMemberDetail>
        data={staffMembers}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={goToPage}
        isLoading={isLoading}
        emptyMessage="No staff members found"
      />
    </div>
  )
}

